INSERT INTO `ai_logs` VALUES (1,3,NULL,NULL,'analisis_gambar_kerusakan','Analisis foto display proyektor buram dan bergaris vertikal kuning.','Terdeteksi degradasi panel optik proyektor LCD dan kemungkinan kotoran debu pada lensa prisma. Rekomendasi: pembersihan prisma dan kalibrasi optik.','{\"model\": \"gemini-1.5-flash\", \"category\": \"display_optical\", \"confidence\": 0.92}','sukses',1240,'2026-09-05 03:44:32'),(2,1,'Berapa jumlah fasilitas yang rusak berat?','Berdasarkan data terkini di database sarana dan prasarana kampus STMIK IKMI Cirebon:\n\nSaat ini **tidak terdapat fasilitas dengan kondisi Rusak berat** (0 item / 0 unit).\n\nSeluruh fasilitas dalam master data berada dalam kondisi operasional lainnya (misalnya berkondisi *Baik* atau *Rusak Ringan*).','ai_assistant','Berapa jumlah fasilitas yang rusak berat?','Berdasarkan data terkini di database sarana dan prasarana kampus STMIK IKMI Cirebon:\n\nSaat ini **tidak terdapat fasilitas dengan kondisi Rusak berat** (0 item / 0 unit).\n\nSeluruh fasilitas dalam master data berada dalam kondisi operasional lainnya (misalnya berkondisi *Baik* atau *Rusak Ringan*).','{\"entity\": \"rusak_berat\", \"intent\": \"COUNT_CONDITION\", \"method\": \"countFacilitiesByCondition\", \"provider\": \"IKMI Deterministic Grounding Engine (Offline)\"}','sukses',2,'2026-10-09 22:36:47'),(3,1,'Fasilitas apa yang paling banyak mengalami kerusakan?','Berdasarkan riwayat tiket pengaduan kerusakan dan catatan servis pemeliharaan di database:\n\nFasilitas yang **paling banyak mengalami kerusakan** adalah **Epson EB-X51 Proyektor XGA 3800 Lumens** (Kode: `INV-2022-PRJ-011`) yang berlokasi di **Ruang Kuliah Teori 201 (Gedung Rektorat & Akademik Utama)** dengan akumulasi **2 insiden** (1 laporan kerusakan & 1 tindakan servis perbaikan).\n\nDaftar fasilitas dengan frekuensi kerusakan tertinggi:\n1. **Epson EB-X51 Proyektor XGA 3800 Lumens** — 2 Kasus (1 Laporan, 1 Servis)\n   • Lokasi: Ruang Kuliah Teori 201 (Gedung Rektorat & Akademik Ut